      const operator = take();
      left = binary(operator, left, sum());
    }
    return left;
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = power();
    while (['*', '/', '//', '%'].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, power());
    }
    return left;
  }

  function unary() {
    if (is('+') || is('-')) {
      return { type: 'unary', operator: take(), operand: unary() };
